def stable_unique(items):
    """Return a list of hashable values from items, preserving first occurrence order."""
    seen = set()
    result = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result


def frequencies(items):
    """Return a dict mapping each hashable value in items to its occurrence count."""
    counts = {}
    for item in items:
        counts[item] = counts.get(item, 0) + 1
    return counts


def chunked(items, size):
    """Split items into chunks of given size; last chunk may be shorter. Raise ValueError if size <= 0."""
    if size <= 0:
        raise ValueError("size must be positive")
    items = list(items)
    if not items:
        return []
    return [items[i:i + size] for i in range(0, len(items), size)]


def running_totals(numbers):
    """Return a list of cumulative sums of numbers. Empty input yields []."""
    result = []
    total = 0
    for num in numbers:
        total += num
        result.append(total)
    return result


def merge_intervals(intervals):
    """Merge overlapping or touching [start, end] intervals and return sorted non-overlapping intervals."""
    if not intervals:
        return []
    sorted_intervals = sorted(intervals, key=lambda x: x[0])
    merged = [list(sorted_intervals[0])]
    for start, end in sorted_intervals[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            merged[-1][1] = max(last_end, end)
        else:
            merged.append([start, end])
    return merged


def lower_bound(values, target):
    """Return the first index in ascending sorted values where value >= target, or len(values)."""
    lo, hi = 0, len(values)
    while lo < hi:
        mid = (lo + hi) // 2
        if values[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo


def rotate_right(items, k):
    """Return a new list rotated right by k modulo its length; negative k rotates left. Empty input yields []."""
    items = list(items)
    n = len(items)
    if n == 0:
        return []
    k = k % n
    if k == 0:
        return items[:]
    return items[-k:] + items[:-k]


def moving_average(numbers, window):
    """Return means of complete consecutive windows using a linear sliding window. Raise ValueError if window <= 0."""
    if window <= 0:
        raise ValueError("window must be positive")
    numbers = list(numbers)
    n = len(numbers)
    if window > n:
        return []
    result = []
    window_sum = 0
    for i in range(n):
        window_sum += numbers[i]
        if i >= window:
            window_sum -= numbers[i - window]
        if i >= window - 1:
            result.append(window_sum / window)
    return result

def validate_matrix(matrix):
    """Validate that matrix is a non-empty list of non-empty lists of equal length. Returns (row_count, column_count). Raises ValueError if invalid."""
    if not isinstance(matrix, list) or len(matrix) == 0:
        raise ValueError("Matrix must be a non-empty list of lists")
    row_count = len(matrix)
    col_count = None
    for row in matrix:
        if not isinstance(row, list) or len(row) == 0:
            raise ValueError("Matrix rows must be non-empty lists")
        if col_count is None:
            col_count = len(row)
        elif len(row) != col_count:
            raise ValueError("Matrix must be rectangular (all rows same length)")
    return (row_count, col_count)

def zeros(rows, cols):
    """Return a rows x cols matrix of zeros. rows and cols must be positive integers. Raises ValueError otherwise."""
    if not isinstance(rows, int) or not isinstance(cols, int):
        raise ValueError("rows and cols must be integers")
    if rows <= 0 or cols <= 0:
        raise ValueError("rows and cols must be positive integers")
    return [[0 for _ in range(cols)] for _ in range(rows)]

def identity(n):
    """Return an n x n identity matrix. n must be a positive integer. Raises ValueError otherwise."""
    if not isinstance(n, int):
        raise ValueError("n must be an integer")
    if n <= 0:
        raise ValueError("n must be a positive integer")
    result = [[0 for _ in range(n)] for _ in range(n)]
    for i in range(n):
        result[i][i] = 1
    return result

def transpose(matrix):
    """Return the transpose of matrix. Validates matrix first. Raises ValueError if invalid."""
    rows, cols = validate_matrix(matrix)
    return [[matrix[i][j] for i in range(rows)] for j in range(cols)]

def add(a, b):
    """Return the elementwise sum of matrices a and b. Both must be valid and have the same shape. Raises ValueError otherwise."""
    a_rows, a_cols = validate_matrix(a)
    b_rows, b_cols = validate_matrix(b)
    if a_rows != b_rows or a_cols != b_cols:
        raise ValueError("Matrices must have the same dimensions for addition")
    return [[a[i][j] + b[i][j] for j in range(a_cols)] for i in range(a_rows)]

def subtract(a, b):
    """Return the elementwise difference a - b. Both must be valid and have the same shape. Raises ValueError otherwise."""
    a_rows, a_cols = validate_matrix(a)
    b_rows, b_cols = validate_matrix(b)
    if a_rows != b_rows or a_cols != b_cols:
        raise ValueError("Matrices must have the same dimensions for subtraction")
    return [[a[i][j] - b[i][j] for j in range(a_cols)] for i in range(a_rows)]

def scale(matrix, scalar):
    """Return a new matrix where every element of matrix is multiplied by scalar. Validates matrix first. Raises ValueError if invalid."""
    rows, cols = validate_matrix(matrix)
    return [[matrix[i][j] * scalar for j in range(cols)] for i in range(rows)]

def matmul(a, b):
    """Return the matrix product a * b. Validates both matrices. Requires columns of a equal rows of b. Raises ValueError otherwise."""
    a_rows, a_cols = validate_matrix(a)
    b_rows, b_cols = validate_matrix(b)
    if a_cols != b_rows:
        raise ValueError("Columns of a must equal rows of b for matrix multiplication")
    result = [[0 for _ in range(b_cols)] for _ in range(a_rows)]
    for i in range(a_rows):
        for j in range(b_cols):
            s = 0
            for k in range(a_cols):
                s += a[i][k] * b[k][j]
            result[i][j] = s
    return result

def row_sums(matrix):
    """Return a list of the sum of each row in matrix. Validates matrix first. Raises ValueError if invalid."""
    rows, cols = validate_matrix(matrix)
    return [sum(matrix[i]) for i in range(rows)]

def col_sums(matrix):
    """Return a list of the sum of each column in matrix. Validates matrix first. Raises ValueError if invalid."""
    rows, cols = validate_matrix(matrix)
    return [sum(matrix[i][j] for i in range(rows)) for j in range(cols)]

def trace(matrix):
    """Return the sum of the diagonal elements of a square matrix. Validates matrix first. Raises ValueError if not square."""
    rows, cols = validate_matrix(matrix)
    if rows != cols:
        raise ValueError("Matrix must be square for trace")
    return sum(matrix[i][i] for i in range(rows))

def matrix_power(matrix, exponent):
    """Return matrix raised to a nonnegative integer exponent using exponentiation by squaring. Matrix must be square. Raises ValueError if invalid."""
    if not isinstance(exponent, int):
        raise ValueError("Exponent must be an integer")
    if exponent < 0:
        raise ValueError("Exponent must be nonnegative")
    rows, cols = validate_matrix(matrix)
    if rows != cols:
        raise ValueError("Matrix must be square for matrix_power")
    n = rows
    if exponent == 0:
        return identity(n)
    if exponent == 1:
        return [row[:] for row in matrix]
    if exponent % 2 == 0:
        half = matrix_power(matrix, exponent // 2)
        return matmul(half, half)
    else:
        half = matrix_power(matrix, exponent - 1)
        return matmul(half, matrix)
